document.addEventListener('DOMContentLoaded',()=>{const avNonce=av_settings.nonce;let avFiles=[];let avFilesLoaded;function checkThemeFile(current=0){const id=parseInt(current);const file=avFiles[id];ajaxRequest({_theme_file:file,_action_request:'check_theme_file',}).then((res)=>res.text()).then((input)=>{if(input){input=JSON.parse(input);if(!input.nonce||input.nonce!==avNonce){return}
const row=document.getElementById(`av-scan-result-${id}`);row.classList.replace('av-status-pending','av-status-warning');row.querySelector('td.av-status-column').innerText=wp.i18n.__('! Warning','antivirus');const lines=input.data;for(let i=0;i<lines.length;i=i+3){const md5=lines[i+2];const line=lines[i+1].replace(/@span@/g,'<span>').replace(/@\/span@/g,'</span>');row.querySelector('td.av-file-column').innerHTML+=`<p><code>${line}</code> <a href="#" id="av-dismiss-${md5}" class="button" `+`title="${wp.i18n.__('Dismiss false positive virus detection', 'antivirus')}">`+wp.i18n.__('Dismiss','antivirus')+'</a></p>';document.getElementById(`av-dismiss-${md5}`)?.addEventListener('click',handleDismiss)}}else{const row=document.getElementById(`av-scan-result-${id}`);row.classList.add('av-status-pending','av-status-ok');row.querySelector('td.av-status-column').innerText=wp.i18n.__('✔ OK','antivirus')}
avFilesLoaded++;if(avFilesLoaded>=avFiles.length){scanSuccess()}else{checkThemeFile(id+1)}}).catch(scanFailed)}
function handleDismiss(evt){ajaxRequest({_file_md5:evt.target.id.substring(11),_action_request:'update_white_list',}).then((res)=>res.json()).then((res)=>{if(!res||!res.nonce||res.nonce!==avNonce){return}
const issue=document.getElementById(`av-dismiss-${res.data[0]}`)?.parentElement;const col=issue?.parentElement;issue?.remove();if(col.getElementsByTagName('p').length===0){col.parentElement?.classList.replace('av-status-warning','av-status-ok');col.parentElement.querySelector('td.av-status-column').innerText=wp.i18n.__('✔ OK','antivirus')}}).catch(scanFailed);return!1}
function triggerScan(evt){evt.target.disabled=!0;ajaxRequest({_action_request:'get_theme_files',}).then((res)=>res.json()).then((input)=>{if(!input){return}
if(!input.nonce||input.nonce!==avNonce){return}
avFiles=input.data;avFilesLoaded=0;let elem=document.getElementById('av-scan-process');if(elem){elem.innerHTML='<span class="spinner is-active" title="running"></span>'}
elem=document.getElementById('av-scan-output');if(elem){elem.innerHTML=generateThemeFileTable()}
checkThemeFile()}).catch(scanFailed);return!1}
function scanSuccess(){document.getElementById('av-scan-process').innerHTML=`<span class="av-scan-complete">${wp.i18n.__('Scan finished', 'antivirus')}</span>`;document.getElementById('av-scan-trigger').disabled=!1}
function scanFailed(){document.getElementById('av-scan-process').innerHTML=`<span class="av-scan-error">${wp.i18n.__('Scan failed', 'antivirus')}</span>`;document.getElementById('av-scan-trigger').disabled=!1}
function generateThemeFileTable(){let output='<table class="wp-list-table widefat fixed striped table-view-list av-scan-results">'+'<thead><tr>'+'<td class="av-toggle-column check-column"></td>'+`<th class="av-file-column">${wp.i18n.__('Theme File', 'antivirus')}</th>`+`<th class="av-status-column">${wp.i18n.__('Check Status', 'antivirus')}</th>`+'</tr></thead>'+'<tbody>';avFiles.forEach((val,i)=>{output+=`<tr id="av-scan-result-${i}" class="av-status-pending">`+'<td class="av-toggle-column check-column"></td>'+`<td class="av-file-column">${val}</td>`+`<td class="av-status-column">${wp.i18n.__('pending', 'antivirus')}</td>`+'</tr>'});output+='</tbody><tfoot><tr>'+'<td class="av-toggle-column check-column"></td>'+`<th class="av-file-column">${wp.i18n.__('Theme File', 'antivirus')}</th>`+`<th class="av-status-column">${wp.i18n.__('Check Status', 'antivirus')}</th>`+'</tr></tfoot></table>';return output}
function manageOptions(){const cbIds=['av_cronjob_enable','av_safe_browsing','av_checksum_verifier',];let anyEnabled=!1;for(const c of cbIds){const cb=document.getElementById(c);if(!cb){continue}
const enabled=cb.checked;cb?.closest('fieldset')?.querySelectorAll('input[type="text"], input[type="checkbox"]').forEach((input)=>{if(input!==cb){input.disabled=!enabled}});anyEnabled=anyEnabled||enabled}
const elem=document.getElementById('av_notify_email');if(elem){elem.disabled=!anyEnabled}}
function ajaxRequest(data){return fetch(ajaxurl,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded',},body:new URLSearchParams({action:'get_ajax_response',_ajax_nonce:avNonce,...data,}),})}
document.getElementById('av-scan-trigger')?.addEventListener('click',triggerScan);document.getElementById('av_settings')?.querySelectorAll('input[type=checkbox]').forEach((cb)=>cb.addEventListener('click',manageOptions));manageOptions()})